/**
 * Bundled offline food database. Nutrients are per 100 g (100 ml for liquids).
 *
 * Values are transcribed from USDA FoodData Central (SR Legacy / Foundation,
 * FNDDS survey values for prepared dishes) as best known. NONE of the entries
 * were confirmed against a fetched USDA record (the API key was rate limited),
 * so every entry is `verified: false`. Flip the flag only after confirming a
 * record. Foods with no USDA equivalent (labneh, halloumi, protein products,
 * regional dishes) are typical-label or recipe-based estimates.
 *
 * Tuple order: [kcal, protein, carbs, fat, fiber, sugar, satFat, sodiumMg]
 */
import type { Food } from '@/types';

type N = [number, number, number, number, number?, number?, number?, number?];
type S = [string, number][];

const f = (id: string, name: string, emoji: string, category: string, n: N, servings: S): Food => ({
  id: `b_${id}`,
  name,
  emoji,
  category,
  source: 'builtin',
  verified: false,
  per100g: {
    kcal: n[0],
    protein: n[1],
    carbs: n[2],
    fat: n[3],
    ...(n[4] !== undefined && { fiber: n[4] }),
    ...(n[5] !== undefined && { sugar: n[5] }),
    ...(n[6] !== undefined && { satFat: n[6] }),
    ...(n[7] !== undefined && { sodium: n[7] }),
  },
  servings: servings.map(([label, grams]) => ({ label, grams })),
});

